texCoord0 = UV0;
// World position: Position is relative to the camera, which is at CameraBlockPos - CameraOffset.
vec3 worldPos = Position + vec3(CameraBlockPos) - CameraOffset;
if (worldPos.x > 3.0) {
    #ifdef PER_FACE_LIGHTING
    vertexPerFaceColorBack.rgb *= vec3(0.3, 0.5, 1.0);
    vertexPerFaceColorFront.rgb *= vec3(0.3, 0.5, 1.0);
    #else
    vertexColor.rgb *= vec3(0.3, 0.5, 1.0);
    #endif
}
